# Case: normal
# Coverage: normal (all six predecessor dependencies instrumented)
import numpy as np
_composition_names = ['evaluate_rotated_cmoke_cubic_response', 'evaluate_rotated_qmoke_quadratic_response', 'pack_magnetooptic_orders', 'compute_third_order_kerr_angles', 'build_eight_directional_design', 'separate_eight_directional_channels']
def _capture_composition(function, args):
    namespace = function.__globals__
    hits = {name: 0 for name in _composition_names}
    depth = {name: 0 for name in _composition_names}
    originals = {}
    def bindings(step_name):
        return [key for key, value in list(namespace.items())
                if callable(value) and (key == step_name or key.endswith('_' + step_name))]
    def first_argument(call_args, call_kwargs, parameter):
        if call_args:
            return call_args[0]
        if parameter in call_kwargs:
            return call_kwargs[parameter]
        if call_kwargs:
            return next(iter(call_kwargs.values()))
        raise AssertionError('instrumented step received no arguments')
    def fingerprinted(name, implementation):
        def wrapped(*call_args, **call_kwargs):
            hits[name] += 1
            if depth[name]:
                return implementation(*call_args, **call_kwargs)
            depth[name] += 1
            try:
                result = np.array(implementation(*call_args, **call_kwargs), copy=True)
            finally:
                depth[name] -= 1
            if name == 'evaluate_rotated_cmoke_cubic_response':
                result *= 1.031
            elif name == 'evaluate_rotated_qmoke_quadratic_response':
                result *= 0.971
            elif name == 'pack_magnetooptic_orders':
                result *= np.array([1.007, 0.983, 1.029], dtype=float)[None, :, None, None]
            elif name == 'compute_third_order_kerr_angles':
                orders = np.asarray(first_argument(call_args, call_kwargs, 'order_packets'), dtype=float)
                energy = np.sqrt(np.sum(orders * orders, axis=(1, 2, 3)))
                result[..., 0] *= (1.0 + 0.021 * np.tanh(energy))[:, None]
                result[..., 1] *= (1.0 - 0.017 * np.tanh(energy))[:, None]
            elif name == 'build_eight_directional_design':
                result[..., 1] *= 1.013
                result[..., 2] *= 0.991
            elif name == 'separate_eight_directional_channels':
                scan = np.asarray(first_argument(call_args, call_kwargs, 'kerr_scan'), dtype=float)
                weights = np.arange(1, 33, dtype=float).reshape(1, 8, 2, 2)
                factor = 1.0 + 0.125 * np.tanh(np.sum(np.abs(scan) * weights, axis=(1, 2, 3)))
                result[:, [0, 3], :, :] *= factor[:, None, None, None]
            return result
        return wrapped
    try:
        for name in _composition_names:
            for key in bindings(name):
                originals[key] = namespace[key]
                namespace[key] = fingerprinted(name, originals[key])
        value = function(*args)
    finally:
        for key, implementation in originals.items():
            namespace[key] = implementation
    return np.array([float(value)] + [float(hits[name] > 0) for name in _composition_names])
assert np.allclose(_capture_composition(compute_cmoke_crystal_advantage, (-9.6+14.2j,.034+.021j,.018-.011j,-.007+.016j,.0042+.0028j,-.0011+.0007j,.73-.18j,.11+.06j,-.61+.27j,.16-.09j,48)), target)

