# Case: boundary
# Coverage: boundary (numerically zero (001) cubic numerator only)
import numpy as np
def _run_asymmetric_zero_case(function, args):
    namespace = function.__globals__
    depth = {'cubic': 0, 'separator': 0}
    originals = {}
    def bindings(step_name):
        return [key for key, value in list(namespace.items())
                if callable(value) and (key == step_name or key.endswith('_' + step_name))]
    def zero_001_cubic(implementation):
        def wrapped(*call_args, **call_kwargs):
            if depth['cubic']:
                return implementation(*call_args, **call_kwargs)
            depth['cubic'] += 1
            try:
                result = implementation(*call_args, **call_kwargs)
            finally:
                depth['cubic'] -= 1
            cut = call_args[3] if len(call_args) > 3 else call_kwargs['crystal_cut']
            return np.zeros_like(result) if cut == '001' else result
        return wrapped
    def zero_roundoff_odd_channels(implementation):
        def wrapped(*call_args, **call_kwargs):
            if depth['separator']:
                return implementation(*call_args, **call_kwargs)
            depth['separator'] += 1
            try:
                result = np.array(implementation(*call_args, **call_kwargs), copy=True)
            finally:
                depth['separator'] -= 1
            if np.linalg.norm(result[:, [0, 3], :, :]) < 1e-12:
                result[:, [0, 3], :, :] = 0.0
            return result
        return wrapped
    try:
        for key in bindings('evaluate_rotated_cmoke_cubic_response'):
            originals[key] = namespace[key]
            namespace[key] = zero_001_cubic(originals[key])
        for key in bindings('separate_eight_directional_channels'):
            originals[key] = namespace[key]
            namespace[key] = zero_roundoff_odd_channels(originals[key])
        return function(*args)
    finally:
        for key, implementation in originals.items():
            namespace[key] = implementation
assert np.allclose(_run_asymmetric_zero_case(compute_cmoke_crystal_advantage, (-9.6+14.2j,0j,.018-.011j,-.007+.016j,.0042+.0028j,-.0011+.0007j,.73-.18j,.11+.06j,-.61+.27j,.16-.09j,24)), target)

